using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Web.Script.Serialization;
namespace PZ3D {static class SnapshotManifestCapacityTests {
 static int checks;static readonly BindingFlags Flags=BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 static void Check(bool value,string reason){if(!value)throw new Exception("FAIL "+reason);checks++;Console.WriteLine("PASS "+reason);}
 static object Call(string name,params object[] args){var method=typeof(SaveEnvironments).GetMethod(name,Flags);Check(method!=null,"production manifest helper exists: "+name);try{return method.Invoke(null,args);}catch(TargetInvocationException error){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(error.InnerException).Throw();throw;}}
 static SaveEnvironmentFile Copy(SaveEnvironmentFile file,string path){return new SaveEnvironmentFile{Path=path,Hash=file.Hash,Bytes=file.Bytes,WriteTicks=file.WriteTicks,Directory=file.Directory};}
 static SaveEnvironmentRecord Model(int count){string root=Path.Combine(Path.GetTempPath(),"ozl-metadata-model");var files=new List<SaveEnvironmentFile>();int gameCount=Math.Min(50000,count/3);var game=new SaveEnvironmentFile[gameCount];for(int i=0;i<game.Length;i++){bool dir=i%16==0;game[i]=new SaveEnvironmentFile{Path="media/lua/shared/Translate/EN/OriginalGameDefinitionAssets/"+i.ToString("D6")+(dir?"-directory":"-item-clothing-definition.json"),Directory=dir,Hash=dir?null:i.ToString("x64"),Bytes=dir?0:4096+i,WriteTicks=dir?0:638000000000000000L};files.Add(Copy(game[i],"game/"+game[i].Path));}if(game.Length>1){files[1].Hash=new string('a',64);files[1].Bytes++;}
  var roots=new List<SaveEnvironmentModRoot>();int remaining=count-gameCount;for(int r=0;r<8;r++){int size=remaining/(8-r);remaining-=size;var source=new SaveEnvironmentFile[size];string prefix="mods/"+r.ToString("D4")+"/mods/CapturedWorkshopRootWithIndependentVersionedFiles"+r;for(int i=0;i<size;i++){bool dir=i%16==0;source[i]=new SaveEnvironmentFile{Path="42.21/media/lua/shared/Translate/"+(i%32==0?"中文":"EN")+"/LongWorkshopDefinitionFolder/"+i.ToString("D6")+(dir?"-directory":"-weapons-clothing-definition.json"),Directory=dir,Hash=dir?null:(r*30000+i+100000).ToString("x64"),Bytes=dir?0:1024+i,WriteTicks=dir?0:638000000000000000L};files.Add(Copy(source[i],prefix+"/"+source[i].Path));}if(size>1)source[1].WriteTicks+=10000000;Array.Sort(source,(a,b)=>StringComparer.OrdinalIgnoreCase.Compare(a.Path,b.Path));roots.Add(new SaveEnvironmentModRoot{SourceRoot=Path.Combine(root,"live","mod"+r),CopiedRoot=Path.Combine(root,prefix.Replace('/',Path.DirectorySeparatorChar)),Layout=Path.Combine(root,prefix.Replace('/',Path.DirectorySeparatorChar),"42.21"),WorkshopId=(1000+r).ToString(),ModIds=new[]{"Mod"+r},SourceFiles=source});}
  return new SaveEnvironmentRecord{Id=new string('a',32),Name="metadata-only capacity model",RootPath=root,GamePath=Path.Combine(root,"game"),SourceGame=Path.Combine(root,"source-game"),UserPath=Path.Combine(root,"user"),RuntimeHome=Path.Combine(root,"runtime","home"),ManifestPath=Path.Combine(root,SaveEnvironments.ManifestName),SaveId="Sandbox/Model",GameVersion="42.21.0",CreatedUtc="2026-10-27T00:00:00Z",RootIdentity="1:2:3",SourceGameIdentity="1:2:4",UserIdentity="1:2:5",SaveConfigHash=new string('b',64),ModIds=roots.SelectMany(row=>row.ModIds).ToArray(),DefaultModIds=new string[0],PreloadModIds=new string[0],Maps=new string[0],ModRoots=roots.ToArray(),GameSourceFiles=game,Files=files.ToArray()};
 }
 static bool Equal(SaveEnvironmentFile[] a,SaveEnvironmentFile[] b){return a.Length==b.Length&&a.Zip(b,(x,y)=>x.Path==y.Path&&x.Hash==y.Hash&&x.Bytes==y.Bytes&&x.WriteTicks==y.WriteTicks&&x.Directory==y.Directory).All(ok=>ok);}
 static object Record(object manifest){return manifest.GetType().GetField("Record").GetValue(manifest);}
 static void RoundTrip(int count){var watch=Stopwatch.StartNew();var row=Model(count);long sourceTick=row.ModRoots[0].SourceFiles[1].WriteTicks,estimate=(long)Call("EstimateManifestBytes",row,row.Files);byte[] bytes=(byte[])Call("EncodeManifest",row,row.Files);Check(bytes.Length<=134217728,"schema2 model stays within bounded 128 MiB: "+count+" rows / "+bytes.Length+" bytes");Check(estimate>=bytes.Length&&estimate<=134217728,"metadata-only capacity bound covers the encoded bytes and admits the representative model: "+count+" / "+estimate);var decoded=(SaveEnvironmentRecord)Record(Call("DecodeManifest",bytes));Check(Equal(row.Files,decoded.Files),"all frozen rows round-trip exactly: "+count);Check(Equal(row.GameSourceFiles,decoded.GameSourceFiles),"game source hashes remain independent of runtime-prepared frozen files: "+count);Check(row.ModRoots.Zip(decoded.ModRoots,(a,b)=>Equal(a.SourceFiles,b.SourceFiles)).All(ok=>ok),"all source mod rows and sparse original timestamps rebuild exactly: "+count);Check(row.ModRoots.All(mapping=>mapping.SourceFiles!=null)&&row.ModRoots[0].SourceFiles[1].WriteTicks==sourceTick,"wire compaction leaves live source arrays and original timestamps untouched: "+count);Console.WriteLine("MODEL "+count+" rows bytes="+bytes.Length+" estimatedBytes="+estimate+" elapsedMs="+watch.ElapsedMilliseconds+" peakWorkingSet="+Process.GetCurrentProcess().PeakWorkingSet64);}
 static void CompatibilityAndLimits(){var row=Model(100);Type type=typeof(SaveEnvironments).GetNestedType("Manifest",BindingFlags.NonPublic);object old=Activator.CreateInstance(type,true);type.GetField("Record").SetValue(old,row);type.GetField("Files").SetValue(old,row.Files);var json=new JavaScriptSerializer{MaxJsonLength=134217728};byte[] legacy=Encoding.UTF8.GetBytes(json.Serialize(old));var read=(SaveEnvironmentRecord)Record(Call("DecodeManifest",legacy));Check(Equal(row.ModRoots[0].SourceFiles,read.ModRoots[0].SourceFiles),"schema1 manifests retain their original source rows without rebuilding from frozen timestamps");
  bool rejected=false;try{Call("EncodeManifest",row,new SaveEnvironmentFile[250001]);}catch(IOException){rejected=true;}Check(rejected,"over-limit row count is refused before serialization");byte[] valid=(byte[])Call("EncodeManifest",row,row.Files);string wire=Encoding.UTF8.GetString(valid);Check(wire.Contains("\"Schema\":2")&&!wire.Contains("\"SourceFiles\":["),"schema2 wire omits duplicate mod source arrays");rejected=false;try{Call("DecodeManifest",Encoding.UTF8.GetBytes(wire.Replace("\"Schema\":2","\"Schema\":3")));}catch(IOException){rejected=true;}Check(rejected,"unknown manifest format is rejected");
 }
 static void ProgressAndCleanup(){string root=Path.Combine(Path.GetTempPath(),"ozl-manifest-events-"+Guid.NewGuid().ToString("N"));try{string game=Path.Combine(root,"game"),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);Directory.CreateDirectory(Path.Combine(user,"Saves","Sandbox","Model"));File.WriteAllText(Path.Combine(game,"ProjectZomboid64.exe"),"synthetic game");File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");File.WriteAllText(Path.Combine(game,"version.txt"),"42.21.0");File.WriteAllText(Path.Combine(game,"game-version.txt"),"42.21.0");File.WriteAllText(Path.Combine(user,"Saves","Sandbox","Model","mods.txt"),"mods\n{\n}\nmaps\n{\n}\n");var store=new SaveEnvironments(new Engine(game,user,data,true));var events=new List<SaveEnvironmentProgress>();var plan=store.Preview("Sandbox/Model");Check(plan.ready,"small real metadata fixture previews before progress verification");string failure="";try{store.Create("Sandbox/Model",Path.Combine(root,"failed"),"failed",plan.stamp,System.Threading.CancellationToken.None,null,row=>{throw new IOException("original preparation failure");},row=>{events.Add(row);if(row.stage=="snapshot-cleanup")throw new Exception("progress observer failure");});}catch(IOException error){failure=error.Message;}
  Check(failure=="original preparation failure"&&events.Any(row=>row.stage=="snapshot-cleanup"&&row.value==-1)&&!Directory.Exists(Path.Combine(root,"failed"))&&!Directory.GetDirectories(root,"*.partial-*").Any(),"cleanup activity survives failure observers without hiding the original error or retaining the partial snapshot");Check(events.Where(row=>row.stage=="manifest-capacity").All(row=>row.completedFiles==0&&row.completedBytes==0)&&events.Any(row=>row.stage=="manifest-capacity"&&row.totalItems>0),"metadata capacity progress uses item counts rather than pretending to copy payload files or bytes");events.Clear();plan=store.Preview("Sandbox/Model");using(var cancel=new System.Threading.CancellationTokenSource()){bool cancelled=false;try{store.Create("Sandbox/Model",Path.Combine(root,"cancelled"),"cancelled",plan.stamp,cancel.Token,null,row=>{cancel.Cancel();cancel.Token.ThrowIfCancellationRequested();},row=>{events.Add(row);if(row.stage=="snapshot-cleanup")throw new Exception("cancelled progress observer failure");});}catch(OperationCanceledException error){cancelled=error.CancellationToken==cancel.Token;}Check(cancelled&&events.Any(row=>row.stage=="snapshot-cleanup"&&row.value==-1)&&!Directory.Exists(Path.Combine(root,"cancelled"))&&!Directory.GetDirectories(root,"*.partial-*").Any(),"already-cancelled tokens still expose protected cleanup and preserve cancellation");}events.Clear();plan=store.Preview("Sandbox/Model");var saved=store.Create("Sandbox/Model",Path.Combine(root,"saved"),"saved",plan.stamp,System.Threading.CancellationToken.None,null,row=>{},row=>events.Add(row));var saves=events.Where(row=>row.stage=="manifest-save").ToArray();Check(saves.Length==2&&saves[0].completedItems==0&&saves[0].totalItems==saved.Files.Length&&saves[1].completedItems==saved.Files.Length&&saves.All(row=>row.completedFiles==0&&row.completedBytes==0),"manifest construction and completed write expose their own visible item stage");Check(store.Bound("Sandbox/Model").Files.Length==saved.Files.Length,"actual schema2 write is reopened through the registered reader");
 }finally{if(Directory.Exists(root))SnapshotFileSystem.Directories.Delete(root,true);}}
 public static int Main(){LauncherRuntime.Initialize();try{Check(Environment.Is64BitProcess,"large bounded manifest roundtrip runs in the production 64-bit architecture");Call("EncodeManifest",Model(10),Model(10).Files);CompatibilityAndLimits();ProgressAndCleanup();RoundTrip(163688);GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();RoundTrip(250000);Console.WriteLine("MANIFEST CAPACITY PASS: "+checks+" assertions");return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
